{
  "technical_and_design_decisions": [
    "Baseline stack: Java 17+, Spring Framework 6.x / Spring Boot 3.x, Maven multi-module build, JUnit 5 and AssertJ for tests.",
    "U1/U2: Binder (message bus binding) jars are treated as optional runtime dependencies resolved from a Maven repository using Eclipse Aether (Maven Resolver); each binder is loaded in an isolated child-first classloader so conflicting transitive versions (e.g., different spring-data versions) do not collide.",
    "U1: Binding selection order is: explicit deployment property > single binder found on classpath/resolution result > fallback to a default binder; if no binder is resolvable, deployment fails fast with a descriptive error.",
    "U2: A dedicated module-resolver component computes a resolved, de-conflicted artifact graph per module at deployment time, with highest-version-wins plus explicit override properties.",
    "U5: Undeploy is added to the Deployer SPI as an idempotent operation with a single consistent strategy for both jobs and streams; the singlenode (single JVM) deployer implementation stops and deregisters the in-process module instances; a REST endpoint on the Admin app triggers undeploy.",
    "U6: Repository backends are selected via Spring Profiles; the 'local' profile wires an in-memory, ConcurrentHashMap-backed stream repository; the repository abstraction is interface-based so persistent backends can be added later.",
    "U7: XD modules are ported by wrapping existing module logic as Spring Cloud Stream functional modules (source/processor/sink) with auto-configuration; the design is captured in an architecture document plus one proof-of-concept ported module.",
    "U8: Counter metrics are exposed via REST endpoints on the Admin app backed by a pluggable counter repository service; payload format supports dashboard consumption for the firehose | counter demo.",
    "U3: A Dockerfile-based image for s-c-d is built and pushed to DockerHub by CI on every merge to the main branch, tagged with latest and the commit SHA.",
    "U4: The screencast is scripted around the firehose | counter pipe, recorded with screen-capture tooling, lightly edited, and published publicly (e.g., YouTube)."
  ],
  "assumptions": [
    "One experienced developer (the author) performs all work; effort is measured in 8-hour workdays and excludes calendar delays such as review wait times.",
    "An existing s-c-d / s-c-s codebase and repository baseline already exists; this increment builds on it rather than starting from scratch.",
    "CI infrastructure (e.g., Jenkins/Concourse/GitHub Actions) and DockerHub account/credentials are already available.",
    "Design details referenced externally (e.g., PR #19 for undeploy) are accessible and do not need to be reverse-engineered.",
    "A firehose (or simulated equivalent) source and a counter sink are available for demo and metrics validation.",
    "Community/code review feedback cycles are brief and their rework is covered within the testing/hardening activities.",
    "Documentation effort is lightweight (READMEs, config samples, and one design document for U7)."
  ],
  "activities": [
    {
      "activity_id": "1.1",
      "activity_name": "Development environment and build setup",
      "activity_description": "Set up/verify the Maven multi-module build, Java 17 toolchain, baseline CI job, and developer environment for the s-c-d/s-c-s increment.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "1.2",
      "activity_name": "U1: Binder jar inclusion/exclusion spike",
      "activity_description": "Investigate how message bus/binding jars can be included or excluded (classpath layout, classloading options, resolution sources) to inform binding selection and fallback.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "1.3",
      "activity_name": "U1: Binding selection and fallback design + prototype",
      "activity_description": "Define the binding selection order and no-binding fallback mechanism; validate with a small prototype exercising binder isolation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "1.4",
      "activity_name": "U2: Runtime dependency resolution design",
      "activity_description": "Design the Aether-based resolution strategy for handling conflicting jar versions across modules, including override properties and resolution output format.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "1.5",
      "activity_name": "U2: Dependency resolver implementation",
      "activity_description": "Implement the module-resolver component that resolves, de-conflicts, and stages the correct artifacts for module deployment at runtime.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "1.6",
      "activity_name": "U2: Dependency resolution tests",
      "activity_description": "Unit and integration tests covering version-conflict scenarios (e.g., two direct-bind modules with different spring-data versions), overrides, and failure modes.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "1.7",
      "activity_name": "U7: XD module model analysis",
      "activity_description": "Analyze the existing XD module model (types, options, packaging, lifecycle) and catalog what must be preserved when porting to s-c-s modules.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "1.8",
      "activity_name": "U7: s-c-s module foundation design",
      "activity_description": "Brainstorm and document the foundation for porting XD modules to s-c-s (module contract, auto-configuration approach, migration guide outline) and validate with one proof-of-concept ported module.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "2.1",
      "activity_name": "U6: Profile-based repository strategy design",
      "activity_description": "Design the repository abstraction and how Spring Profiles select the backend strategy in the core Admin application.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "2.2",
      "activity_name": "U6: In-memory repository and local profile implementation",
      "activity_description": "Implement the in-memory stream repository and wire it to the 'local' profile; ensure Admin configuration activates the strategy per profile.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "2.3",
      "activity_name": "U6: Profile tests and configuration docs",
      "activity_description": "Tests for profile activation and in-memory repository behavior, plus configuration documentation for selecting backends via profiles.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "2.4",
      "activity_name": "U5: Consistent undeploy strategy design",
      "activity_description": "Determine a consistent undeploy strategy for both jobs and streams (prerequisite from PR #19), including idempotency and error semantics.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "2.5",
      "activity_name": "U5: Undeploy SPI and Admin REST endpoint",
      "activity_description": "Extend the Deployer SPI with undeploy and expose it through the Admin application's controller/REST layer.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "2.6",
      "activity_name": "U5: Singlenode deployer undeploy implementation",
      "activity_description": "Implement undeploy in the singlenode (single JVM) deployer: stop running stream/job module instances, release resources, and deregister them.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "2.7",
      "activity_name": "U5: Undeploy tests",
      "activity_description": "Unit and integration tests for undeploying running streams and jobs on the singlenode target, including repeated/failed undeploy edge cases.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "2.8",
      "activity_name": "U8: Counter metrics endpoint contract design",
      "activity_description": "Define the REST contract (paths, payload format, query options) for exposing counter metrics suitable for dashboard consumption.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "2.9",
      "activity_name": "U8: Counter service and REST endpoints implementation",
      "activity_description": "Implement the counter metrics service backed by a pluggable repository and the Admin REST endpoints exposing counter values.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "2.10",
      "activity_name": "U8: Counter endpoint tests and dashboard validation",
      "activity_description": "Tests for the counter endpoints and validation that a dashboard can consume them for the firehose | counter pipe.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "3.1",
      "activity_name": "U3: s-c-d Dockerfile and local image build",
      "activity_description": "Author the Dockerfile for the s-c-d image and validate building and running it locally.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "3.2",
      "activity_name": "U3: CI pipeline for incremental DockerHub push",
      "activity_description": "Configure the CI pipeline to build the image and push to DockerHub on each merged commit, with latest and commit-SHA tags and credential handling.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "3.3",
      "activity_name": "U3: Publish verification and docs",
      "activity_description": "Verify end-to-end automated publishing to DockerHub and document the image naming, tagging, and usage.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "3.4",
      "activity_name": "U4: Demo environment and screencast script",
      "activity_description": "Prepare the firehose | counter demo environment and write the screencast script showcasing s-c-s and the development experience.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "3.5",
      "activity_name": "U4: Record, edit, and publish screencast",
      "activity_description": "Record the screencast, perform light editing/captioning, and publish it publicly.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "4.1",
      "activity_name": "End-to-end integration testing and hardening",
      "activity_description": "Cross-feature integration testing (deploy/undeploy with binder resolution, profiles, metrics endpoints, container image), bug fixing, and hardening.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "4.2",
      "activity_name": "Final documentation and release notes",
      "activity_description": "Consolidate README/config documentation and write release notes covering U1-U8 deliverables.",
      "most_likely_effort": 1.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 45
  }
}

